-- Professional Project Dashboard demo data seed
-- Project date values are stored in ISO format for PostgreSQL compatibility.
-- Run after supabase/schema.sql and after creating the demo Auth users.
-- This script is idempotent for demo project legacy IDs project-01 through project-10.

begin;

create temp table if not exists demo_project_keys(legacy_id text primary key) on commit drop;
delete from demo_project_keys;
insert into demo_project_keys(legacy_id) values
  ('project-01'),
  ('project-02'),
  ('project-03'),
  ('project-04'),
  ('project-05'),
  ('project-06'),
  ('project-07'),
  ('project-08'),
  ('project-09'),
  ('project-10')
on conflict do nothing;


-- Remove previous demo rows for the same project keys.
delete from public.audit_logs where project_id in (select id from public.projects where legacy_id in (select legacy_id from demo_project_keys));
delete from public.project_schedule_events where project_id in (select id from public.projects where legacy_id in (select legacy_id from demo_project_keys));
delete from public.project_branding where project_id in (select id from public.projects where legacy_id in (select legacy_id from demo_project_keys));
delete from public.meeting_logs where project_id in (select id from public.projects where legacy_id in (select legacy_id from demo_project_keys));
delete from public.document_outputs where project_id in (select id from public.projects where legacy_id in (select legacy_id from demo_project_keys));
delete from public.documents where project_id in (select id from public.projects where legacy_id in (select legacy_id from demo_project_keys));
delete from public.tasks where project_id in (select id from public.projects where legacy_id in (select legacy_id from demo_project_keys));
delete from public.project_members where project_id in (select id from public.projects where legacy_id in (select legacy_id from demo_project_keys));
delete from public.timeline_phases where timeline_item_id in (
  select id from public.timeline_items where project_id in (select id from public.projects where legacy_id in (select legacy_id from demo_project_keys))
);
delete from public.timeline_items where project_id in (select id from public.projects where legacy_id in (select legacy_id from demo_project_keys));
delete from public.project_access where project_id in (select id from public.projects where legacy_id in (select legacy_id from demo_project_keys));
delete from public.projects where legacy_id in (select legacy_id from demo_project_keys);


-- Profiles are created only for Auth users that already exist.

with demo_accounts(email, full_name, role) as (
  values
  ('pm@professional-demo.local', 'Demo Project Manager', 'project_manager'),
  ('admin@professional-demo.local', 'Demo Administrator', 'admin'),
  ('client-project-01@professional-demo.local', 'Demo Client PPD-001', 'guest'),
  ('client-project-02@professional-demo.local', 'Demo Client PPD-002', 'guest'),
  ('client-project-03@professional-demo.local', 'Demo Client PPD-003', 'guest'),
  ('client-project-04@professional-demo.local', 'Demo Client PPD-004', 'guest'),
  ('client-project-05@professional-demo.local', 'Demo Client PPD-005', 'guest'),
  ('client-project-06@professional-demo.local', 'Demo Client PPD-006', 'guest'),
  ('client-project-07@professional-demo.local', 'Demo Client PPD-007', 'guest'),
  ('client-project-08@professional-demo.local', 'Demo Client PPD-008', 'guest'),
  ('client-project-09@professional-demo.local', 'Demo Client PPD-009', 'guest'),
  ('client-project-10@professional-demo.local', 'Demo Client PPD-010', 'guest')
)
insert into public.profiles(id,email,full_name,role)
select u.id, a.email, a.full_name, a.role
from demo_accounts a
join auth.users u on lower(u.email) = lower(a.email)
on conflict(id) do update set
  email = excluded.email,
  full_name = excluded.full_name,
  role = excluded.role,
  updated_at = now();


