insert into public.project_branding(project_id,prepared_for,prepared_by,confidentiality_label,report_footer_text,brand_accent_color,show_client_logo,show_cywa_logo)
select p.id, i.prepared_for, i.prepared_by, i.confidentiality_label, i.report_footer_text, i.brand_accent_color, i.show_client_logo, i.show_cywa_logo
from input i join public.projects p on p.legacy_id = i.legacy_id
on conflict(project_id) do update set
  prepared_for = excluded.prepared_for, prepared_by = excluded.prepared_by, confidentiality_label = excluded.confidentiality_label, report_footer_text = excluded.report_footer_text,
  brand_accent_color = excluded.brand_accent_color, show_client_logo = excluded.show_client_logo, show_cywa_logo = excluded.show_cywa_logo, updated_at = now();


