insert into public.project_schedule_events(project_id,event_date,start_time,end_time,title,event_type,delivery_mode,location,description,is_internal)
select p.id, i.event_date::date, i.start_time::time, i.end_time::time, i.title, i.event_type, i.delivery_mode, i.location, i.description, i.is_internal
from input i join public.projects p on p.legacy_id = i.legacy_id;


-- Project access mappings for demo users.

insert into public.project_access(user_id, project_id, access_role, can_edit, is_enabled)
select pr.id, p.id, pr.role, (pr.role = 'project_manager'), true
from public.profiles pr
cross join public.projects p
where lower(pr.email) in ('pm@professional-demo.local','admin@professional-demo.local')
  and p.legacy_id in (select legacy_id from demo_project_keys)
on conflict(user_id, project_id) do update set access_role = excluded.access_role, can_edit = excluded.can_edit, is_enabled = true;

with input(email, project_code) as (
  values
  ('client-project-01@professional-demo.local', 'PPD-001'),
  ('client-project-02@professional-demo.local', 'PPD-002'),
  ('client-project-03@professional-demo.local', 'PPD-003'),
  ('client-project-04@professional-demo.local', 'PPD-004'),
  ('client-project-05@professional-demo.local', 'PPD-005'),
  ('client-project-06@professional-demo.local', 'PPD-006'),
  ('client-project-07@professional-demo.local', 'PPD-007'),
  ('client-project-08@professional-demo.local', 'PPD-008'),
  ('client-project-09@professional-demo.local', 'PPD-009'),
  ('client-project-10@professional-demo.local', 'PPD-010')
)
insert into public.project_access(user_id, project_id, access_role, can_edit, is_enabled)
select pr.id, p.id, 'guest', false, true
from input i
join public.profiles pr on lower(pr.email) = lower(i.email)
join public.projects p on p.code = i.project_code
on conflict(user_id, project_id) do update set access_role = 'guest', can_edit = false, is_enabled = true;


insert into public.audit_logs(action, table_name, details) values ('seed_demo_data', 'projects', jsonb_build_object('project_count', 10, 'source', 'Professional Project Dashboard demo seed'));

commit;
